PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?entity ?birthDate
WHERE {
  VALUES ?entity { <http://dbpedia.org/resource/Gideon_Johnson_Pillow> <http://dbpedia.org/resource/Holm_Jølsen> }
  ?entity dbo:birthDate ?birthDate .
}
LIMIT 100

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?entity ?birthDate
WHERE {
  VALUES ?entity { <http://dbpedia.org/resource/Marco_de_Luigi> <http://dbpedia.org/resource/Fabio_Maistro> }
  ?entity dbo:birthDate ?birthDate .
}
LIMIT 100

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate
WHERE {
  {
    <http://dbpedia.org/resource/Monster_a_Go-Go> dbo:director ?director .
    ?director dbo:birthDate ?birthDate .
    BIND(<http://dbpedia.org/resource/Monster_a_Go-Go> AS ?film)
  } UNION {
    <http://dbpedia.org/resource/The_Gamecock_(film)> dbo:director ?director .
    ?director dbo:birthDate ?birthDate .
    BIND(<http://dbpedia.org/resource/The_Gamecock_(film)> AS ?film)
  }
}
LIMIT 100
